"""Seed for relationships.json (Deliverable D).
Predicates are a controlled vocabulary; relation_kind is derived from the predicate.
A shared surname or a family tie is NEVER recorded as a business relation unless a source states the business link.
status: VERIFIED | PARTIALLY_VERIFIED | ATTRIBUTED | DISPUTED | UNVERIFIED (criteria in F-research-quality-report.md).
'locators' point to the exact page used where a source record covers many pages (e.g. Olnick Spanu)."""
KIND = {
    "CHILD_OF": "family", "SIBLING_OF": "family", "SON_IN_LAW_OF": "family", "MEMBER_OF_FAMILY": "family",
    "FOUNDED": "business", "CO_FOUNDED": "business", "PARTNER_IN": "business", "OWNER_OF": "business", "MANAGED": "business",
    "ARTISTIC_DIRECTOR_OF": "professional", "DESIGNED_FOR": "professional", "MAESTRO_AT": "professional", "WORKED_AT": "professional",
    "SUCCEEDED_BY": "organisational", "MERGED_INTO": "organisational", "RENAMED_TO": "organisational",
    "NOT_SAME_AS": "identity", "IDENTITY_UNRESOLVED": "identity",
}
def os_(path): return f"https://olnickspanu.com/{path}/"
_n = [0]
def R(s, p, o, *, start=None, end=None, status, src, loc=(), note=""):
    assert p in KIND, p
    _n[0] += 1
    return dict(id=f"REL-{_n[0]:04d}", subject_id=s, predicate=p, object_id=o, relation_kind=KIND[p],
                start=start, end=end, verification_status=status, source_ids=list(src), locators=list(loc), notes=note)

